path = sys.argv[1]
wb = openpyxl.load_workbook(path)
ws = wb['Guiones 2027']
H = [c.value for c in ws[1]]
semanas = {r[0] for r in D}
for row in range(ws.max_row, 1, -1):
    if ws.cell(row, 1).value in semanas: ws.delete_rows(row)
for r in D:
    assert len(r) == len(H), (r[:2], len(r), len(H)); ws.append(list(r))
for row in ws.iter_rows(min_row=2):
    for c in row: c.alignment = Alignment(wrap_text=True, vertical='top')
wb.save(path); print('ok', len(D), 'guiones')
